{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "A high proportion of SARS-CoV-2 patients survive infection but the prevalence of chronic sequelae and resulting disability is increasing. These survivors need clinical management and rehabilitation to facilitate good health outcomes. ... To date, the ClinicalTrials.gov website 2 of the National Library of Medicine has registered more than 6400 clinical studies targeting the epidemiology and management of COVID-19, but only 245 studies (188 of which are ongoing) address rehabilitation in COVID-19 survivors.",
      "reason": "The text describes the current state of knowledge regarding COVID-19 survivors needing rehabilitation and highlights the uncertainty/gap in evidence regarding rehabilitation specifically, noting that while many studies exist for COVID-19, few address rehabilitation."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "The best available research evidence is required to inform management and rehabilitation decisions, interventions, and health systems for COVID-19 survivors with adverse clinical sequelae. Further evidence is warranted to estimate the resources needed to plan for setting appropriate and adequately delivered post-acute and long-term rehabilitation services.",
      "reason": "The text explicitly explains the importance and need for the review, stating that evidence is required to inform management and rehabilitation decisions and to plan for rehabilitation services."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "This rapid living systematic review on rehabilitation and COVID-19 was initiated in April 2020 as a component of the Cochrane Rehabilitation REH-COVER action. 3 Since its inception, it has been updated monthly, with the most recent update leading to a total of 319 papers up to April 30 th , 2021.",
      "reason": "The review identifies itself as an update of a living systematic review, citing previous editions and the ongoing nature of the work."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a broad systematic review of rehabilitation evidence for COVID-19, not a review of a specific intervention's mechanism of action."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review is a broad synthesis of evidence on rehabilitation needs and outcomes, not a review of a specific complex intervention requiring a logic model."
    }
  ],
  "confidence": 100
}

